import { createPrivateKey } from "node:crypto";
import webpush from "web-push";

/**
 * The server's VAPID keys (#261, study 022): they sign every push, and browsers subscribe with the
 * public one. `privateKey` is the raw key and `publicKey` the uncompressed point, both base64url,
 * as the Push API and `web-push` take them.
 */
export type PushKeys = { publicKey: string; privateKey: string; subject: string };

/**
 * VAPID keys from a P-256 private key in PEM (`VAPID_PRIVATE_KEY`: OpenTofu's `tls_private_key` in
 * production, generated by the dev scripts and the end-to-end setup). `subject`: the contact push
 * services may use (`vapidSubject`).
 */
export function vapidKeys(pem: string, subject: string): PushKeys {
  const jwk = createPrivateKey(pem).export({ format: "jwk" });
  if (jwk.crv !== "P-256" || !jwk.d || !jwk.x || !jwk.y) {
    throw new Error("VAPID_PRIVATE_KEY must be a P-256 private key");
  }
  const point = [
    Buffer.from([4]),
    Buffer.from(jwk.x, "base64url"),
    Buffer.from(jwk.y, "base64url"),
  ];
  return { publicKey: Buffer.concat(point).toString("base64url"), privateKey: jwk.d, subject };
}

/**
 * VAPID's contact for the push services: the app's URL when it's HTTPS (production), else the
 * emails' sender address (`MAIL_FROM`, "Name <address>" or the address): VAPID takes only
 * `https:` and `mailto:` (local and end-to-end runs serve plain http).
 */
export function vapidSubject(appUrl: string, mailFrom: string) {
  if (appUrl.startsWith("https:")) return new URL(appUrl).origin;
  return `mailto:${/<([^>]+)>/.exec(mailFrom)?.[1] ?? mailFrom.trim()}`;
}

/**
 * The browsers' push services (Chrome, Firefox, Safari, Edge): the server only sends to these, so a
 * subscription can't make it call any other address. Subdomains included.
 */
export const PUSH_SERVICE_HOSTS = [
  "fcm.googleapis.com",
  "updates.push.services.mozilla.com",
  "push.apple.com",
  "notify.windows.com",
];

/** Whether a subscription's endpoint is one of these push services, over HTTPS. */
export function isPushService(endpoint: string, hosts: readonly string[]) {
  const url = URL.parse(endpoint);
  if (url?.protocol !== "https:") return false;
  return hosts.some((host) => url.hostname === host || url.hostname.endsWith(`.${host}`));
}

/** A device to push to: its subscription as the browser gave it. */
export type PushTarget = { endpoint: string; p256dh: string; auth: string };

/** What a push gives: delivered to the push service, refused, or the device gone (404, 410). */
export type PushResult = "sent" | "failed" | "gone";

/** Sends one push (#262). Never throws: a failure is a result, logged by the caller. */
export type PushSender = {
  send(target: PushTarget, payload: string): Promise<{ result: PushResult; error?: unknown }>;
};

/** How long a push service keeps a push for a device that is offline: a day. */
export const PUSH_TTL_SECONDS = 24 * 60 * 60;

/** Pushes signed with the VAPID keys and encrypted for each device, by `web-push`. */
export function createWebPushSender(keys: PushKeys): PushSender {
  const vapidDetails = {
    subject: keys.subject,
    publicKey: keys.publicKey,
    privateKey: keys.privateKey,
  };
  return {
    async send(target, payload) {
      try {
        await webpush.sendNotification(
          { endpoint: target.endpoint, keys: { p256dh: target.p256dh, auth: target.auth } },
          payload,
          { vapidDetails, TTL: PUSH_TTL_SECONDS },
        );
        return { result: "sent" };
      } catch (error) {
        const status = error instanceof webpush.WebPushError ? error.statusCode : undefined;
        if (status === 404 || status === 410) return { result: "gone" };
        return { result: "failed", error };
      }
    },
  };
}

/** Tests: keeps what was pushed; endpoints listed in `gone` answer as gone, in `failing` fail. */
export function createMemoryPushSender() {
  const sent: { target: PushTarget; payload: unknown }[] = [];
  const gone = new Set<string>();
  const failing = new Set<string>();
  const sender: PushSender = {
    async send(target, payload) {
      if (gone.has(target.endpoint)) return { result: "gone" };
      if (failing.has(target.endpoint))
        return { result: "failed", error: new Error("push failed") };
      sent.push({ target, payload: JSON.parse(payload) });
      return { result: "sent" };
    },
  };
  return { sender, sent, gone, failing };
}
